.ds-folder-picker { width: 850px; max-width: 100%; height: 560px; max-height: 90vh; background: #29262f; border-radius: 14px; box-shadow: 0 22px 90px #0006; display: flex; flex-direction: column; overflow: hidden; outline: none; }
