.ds-picker-layout > nav > button:hover { background: #3a3046; }
.ds-picker-layout > nav > .ds-active { background: #42344f; color: #e6d4fa; }
.ds-picker-main { flex: 1; display: flex; flex-direction: column; min-width: 0; padding: 15px 20px 10px; }
.ds-directory-entries { flex: 1; overflow: auto; }
.ds-directory-entry { display: flex; align-items: center; gap: 11px; width: 100%; padding: 11px 9px; font-size: 11px; text-align: left; color: #c1a6de; border-radius: 5px; }
.ds-directory-entry:hover:not(:disabled) { background: #3d3249; }
.ds-directory-entry > span { flex: 1; color: #d8cde3; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ds-folder-picker > footer { display: flex; gap: 10px; padding: 17px 22px; border-top: 1px solid #43384d; align-items: center; flex: none; }
.ds-folder-picker > footer > span { font-size: 10px; color: #b3a0c7; flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ds-folder-picker > footer > button { font-size: 11px; min-height: 35px; padding: 10px 15px; }
.ds-folder-picker h2 { margin: 0; }
